algorithms.pseudocode:
function generate_digest(reg_type, reg_val64):
    if reg_type == INTEGER:
        trailing_cnt = count_trailing_zeros_or_ones(reg_val64) & 0x3F // 6 bits [5:0]
        leading_cnt = count_leading_zeros_or_ones(reg_val64) & 0x3F   // 6 bits [8:3]
        lsb6 = reg_val64 & 0x3F                                       // 6 bits [11:6]
        digest = (trailing_cnt) ^ (leading_cnt << 3) ^ (lsb6 << 6)
        return digest & 0x0FFF
    elif reg_type == FLOAT:
        format = classify_fp_format(reg_val64)
        if format == FP16:
            // Val[15:13] -> sign and 2 MSBs of exp placed at digest[5:3]
            return ((reg_val64 >> 13) & 0x07) << 3
        elif format == FP32:
            // Value[31:26] -> sign and 5 MSBs of exp placed at digest[8:3]
            return ((reg_val64 >> 26) & 0x3F) << 3
        else: // FP64
            // Value[63:55] -> sign and 8 MSBs of exp placed at digest[11:3]
            return ((reg_val64 >> 55) & 0x1FF) << 3
    elif reg_type == FLAGS:
        // Value[3:0] replicated 3 times filling 12 bits
        flags4 = reg_val64 & 0x0F
        return (flags4 << 8) | (flags4 << 4) | flags4
    return 0

function on_instruction_decode(inst):
    // Age existing valid digests across all entries
    for r in 0 .. 64:
        if register_tracking_table[r].valid == 1:
            if register_tracking_table[r].decay_ctr < 255:
                register_tracking_table[r].decay_ctr += 1
            else:
                register_tracking_table[r].valid = 0
                register_tracking_table[r].decay_ctr = 0

    // Allocate destination register for writing instruction
    if inst.writes_register:
        rd = inst.dest_logical_reg
        if rd >= 0 and rd <= 64:
            register_tracking_table[rd].valid = 0
            register_tracking_table[rd].payload = inst.rob_tag & 0x3FFF
            register_tracking_table[rd].decay_ctr = 0

function on_instruction_complete(rob_tag, rd, reg_type, val64):
    if rd >= 0 and rd <= 64:
        if register_tracking_table[rd].valid == 0 and register_tracking_table[rd].payload == (rob_tag & 0x3FFF):
            register_tracking_table[rd].payload = generate_digest(reg_type, val64)
            register_tracking_table[rd].valid = 1
            register_tracking_table[rd].decay_ctr = 0

function on_pipeline_squash(flushed_rob_tags):
    for r in 0 .. 64:
        if register_tracking_table[r].valid == 0:
            if register_tracking_table[r].payload in flushed_rob_tags:
                // Pending write was squashed; revert to invalid
                register_tracking_table[r].payload = 0
                register_tracking_table[r].decay_ctr = 0
